def bfs_from_points(grid, starts):
    from collections import deque
    visited = set()
    queue = deque(starts)
    while queue:
        r,c = queue.popleft()
        if (r,c) not in visited:
            visited.add((r,c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < 21 and 0 <= nc < 21 and grid[nr][nc] != 5:
                    if (nr,nc) not in visited:
                        queue.append((nr,nc))
    return visited

