def get_component_cells_fast(r, c, grid):
    """Fast BFS for component"""
    seen = set([(r,c)])
    result = [(r,c)]
    q = deque([(r,c)])

    while q:
        cr, cc = q.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr+dr, cc+dc
            if 0 <= nr < 21 and 0 <= nc < 21:
                if grid[nr][nc] == grid[cr][cc] and grid[nr][nc] not in [0,5] and (nr,nc) not in seen:
                    seen.add((nr,nc))
                    result.append((nr,nc))
                    q.append((nr,nc))

    return result

